def solve(inp):
    i=np.array(inp); H,W=i.shape; out=i.copy()
    # key band: contiguous same-column-nonzero rows with >=2 distinct colors
    band=None
    for r0 in range(H):
        pat=frozenset(c for c in range(W) if i[r0,c]!=0)
        k=1
        while r0+k<H and frozenset(c for c in range(W) if i[r0+k,c]!=0)==pat:
            k+=1
        if k>=2 and len({i[r,c] for r in range(r0,r0+k) for c in range(W) if i[r,c]!=0})>=2:
            band=(r0,i[r0:r0+k,:W]); break
    rb,bandv=band
    cols=[c for c in range(bandv.shape[1]) if bandv[0,c]!=0]
    kc=[int(bandv[0,c]) for c in cols]  # left->right colors
    # shapes outside band region: 8-connectivity components of constant nonzero color
    seen=np.zeros_like(i,bool); shapes=[]
    for r in range(H):
        for c in range(W):
            if i[r,c]!=0 and not seen[r,c]:
                col=int(i[r,c]); stack=[(r,c)]; seen[r,c]=True; cells=[]
                while stack:
                    a,b=stack.pop(); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and not seen[x,y] and i[x,y]==col:
                                seen[x,y]=True; stack.append((x,y))
                shapes.append((col,cells))
    scol=set(col for col,_ in shapes)
    missing=[kc[j] for j in range(len(kc)) if kc[j] not in scol]
    shapes.sort(key=lambda s:min(r for r,_ in s[1]))
    for mi,col in enumerate(missing):
        n_shapes=len(shapes)
        if mi < n_shapes:          # attach above even index / below odd? try: above if mi even else below
            ref=shapes[mi]
            h=max(r for r,_ in ref[1])-min(r for r,_ in ref[1])+1
            adj=-1 if mi%2==0 else +1
            off = -(h+1)+min(r for r,_ in ref[1])   # bottom of copy at rr0-1
            if adj==+1: off = max(r for r,_ in ref[1])+1
            for (r,c) in ref[1]:
                rr=r-off
                if 0<=rr<H: out[rr,c]=col
        else:                       # attach to next/prev shape? fallback: above the LAST shape repeatedly
            ref=shapes[-1]
            h=max(r for r,_ in ref[1])-min(r for r,_ in ref[1])+1
            off=min(r for r,_ in ref[1])-h-1
            for (r,c) in ref[1]:
                if 0<=r+off<H: out[r+off,c]=col
    return out.tolist()

