import numpy as np

def solve(inp):
    a=np.array(inp); H,W=a.shape
    # band block = maximal rectangle rows/cols with >=2 distinct colors, but restrict to overlap region? Use: cells whose row AND col are multi-color lines within their common span.
    br=[r for r in range(H) if len({a[r,c] for c in range(W)})>=2]
    bc=[c for c in range(W) if len({a[r,c] for r in range(H)})>=2]
    bcells={(r,c) for r in br for c in bc}
    bcol={int(a[r,c]) for r,c in bcells}
    res=a.copy()
    tmpl=None; tcells=None
    for v in sorted(bcol):
        cells=[(r,c) for r in range(H) for c in range(W) if a[r,c]==v and (r,c) not in bcells]
        if len(cells)>=2: tmpl=v; tcells=cells; break
    miss=sorted([v for v in bcol if v!=tmpl])
    trs=sorted({r for r,_ in tcells}); tmin=min(trs); tmax=max(trs)
    h=tmax-tmin+1
    # near stack: positions just above template, stepping away from band side... determine direction:
    band_above = tmax < min(br)  # template below band -> near stamps go ABOVE template
    def slot(r0): return None
    seq=[]
    if band_above:
        p=tmin-h
        while p > tmax:  # move up while still in grid
            seq.append(p); p-=h
        # far stack: below template, anchored at bottom of grid? demo: last stamp ends at H-2 or so; try flush to bottom-ish: q=tmax+h; go down until fits
        q=tmax+h
        while q + h -1 < H:
            seq.append((tmax,q)); q+=h
    else:
        p=tmax+h
        while p < tmin:
            seq.append((p,tmin)); p+=h
        q=tmin-h
        while q-h >= 0:
            seq.append((q,tmin)); q-=h
    out=res
    for i,v in enumerate(miss):
        p=seq[i]; r0,p0=p if isinstance(p,tuple) else (p,p)
        ok=True
        for (r,c) in tcells:
            if (r0+(r-tmin))==r and True: pass
        # check no collision
        for (r,c) in tcells:
            rr=r0+(r-tmin)
            if not(0<=rr<H): ok=False;break
            if out[rr,c]!=0 and out[rr,c]!=v and (rr,c) not in bcells and (rr,c) not in [(x,y) for x,y in []]:
                pass
        if ok:
            for (r,c) in tcells:
                rr=r0+(r-tmin)
                out[rr,c]=v
    for r,c in bcells: out[r,c]=0
    return out.tolist()

